/// <reference lib="webworker" />
/**
 * Service worker of the PWA (vite-plugin-pwa, `injectManifest`): the offline
 * app shell and the runtime caches (until now generated by Workbox), plus Web
 * Push. The page keeps the session, never this worker (it cannot read the
 * tokens): the only call it makes on its own is the anonymous receipt of a
 * notification.
 */
import { clientsClaim } from 'workbox-core'
import { cleanupOutdatedCaches, createHandlerBoundToURL, precacheAndRoute } from 'workbox-precaching'
import { NavigationRoute, registerRoute } from 'workbox-routing'
import { NetworkFirst, NetworkOnly } from 'workbox-strategies'
import { CacheableResponsePlugin } from 'workbox-cacheable-response'
import { BADGE_CACHE, BADGE_KEY } from './utils/pushBadge'

declare const self: ServiceWorkerGlobalScope

// A new worker takes over at once (registerType: 'autoUpdate')
void self.skipWaiting()
clientsClaim()

// The ?v= content hash of the icon URLs still hits their precached copy
precacheAndRoute(self.__WB_MANIFEST, { ignoreURLParametersMatching: [/^utm_/, /^fbclid$/, /^v$/] })
cleanupOutdatedCaches()

// Never the SPA shell for the dev catch-all mailbox (Mailpit behind nginx),
// nor for the API: a printing sheet opens as a page (PDF)
registerRoute(new NavigationRoute(createHandlerBoundToURL('index.html'), {
  denylist: [/^\/mail\//, /^\/api\//],
}))

registerRoute(
  ({ request, url }) => request.destination === 'document'
    && !url.pathname.startsWith('/mail/') && !url.pathname.startsWith('/api/'),
  new NetworkFirst({
    cacheName: 'pages-cache',
    networkTimeoutSeconds: 3,
    plugins: [new CacheableResponsePlugin({ statuses: [0, 200] })],
  }),
)

// Authentication requests must not be cached
const keycloakUrl = (import.meta.env.VITE_KEYCLOAK_URL || 'https://auth.dev.velutina.ovh/').replace(/\/$/, '')
registerRoute(({ url }) => url.toString().startsWith(keycloakUrl), new NetworkOnly())

// -- Web Push ---------------------------------------------------------------

interface PushPayload {
  /** Id of the delivery, acknowledged once the notification is shown */
  id?: string
  title?: string
  body?: string
  url?: string
  /** Same tag: the notification replaces the previous one (a reminder repeated for the same trap) */
  tag?: string
}

function readPayload(event: PushEvent): PushPayload {
  try {
    return (event.data?.json() as PushPayload) ?? {}
  } catch {
    // Not JSON: show the text as is
    return { body: event.data?.text() }
  }
}

/** One more unseen notification: counted in the cache, then drawn on the app icon. */
async function addToBadge(): Promise<void> {
  try {
    // The app is in front: the person sees the message arrive, nothing to count
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    if (windows.some((client) => client.visibilityState === 'visible')) return

    const cache = await caches.open(BADGE_CACHE)
    const previous = await cache.match(BADGE_KEY)
    const count = (previous ? parseInt(await previous.text(), 10) || 0 : 0) + 1
    await cache.put(BADGE_KEY, new Response(String(count)))
    // Not available everywhere (Android draws its own dot), and refused without the permission
    if ('setAppBadge' in self.navigator) await self.navigator.setAppBadge(count)
  } catch { /* the badge is a convenience: never lose the notification over it */ }
}

self.addEventListener('push', (event) => {
  const payload = readPayload(event)
  event.waitUntil((async () => {
    // A push must always end in a visible notification: iOS and Chrome revoke
    // the permission of a site that receives pushes without showing any
    const options: NotificationOptions & { renotify?: boolean } = {
      body: payload.body,
      icon: import.meta.env.VITE_APP_ICON,
      data: { url: payload.url || '/' },
    }
    if (payload.tag) {
      options.tag = payload.tag
      // A replaced notification still alerts: it is a new reminder
      options.renotify = true
    }
    await self.registration.showNotification(payload.title || 'Velutina', options)
    await addToBadge()
    // Tells the server the device showed it, to measure the delay. Best effort:
    // the notification does not depend on it, and the id is the only credential
    if (payload.id) {
      try {
        await fetch(`/api/push/ack/${encodeURIComponent(payload.id)}/`, { method: 'POST' })
      } catch { /* offline: no receipt */ }
    }
  })())
})

self.addEventListener('notificationclick', (event) => {
  event.notification.close()
  const target = new URL((event.notification.data as { url?: string } | undefined)?.url || '/', self.location.origin).href
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    const open = windows.find((client) => new URL(client.url).origin === self.location.origin)
    if (open) {
      // The app is open: bring it to the front and let its router go to the page
      // (`useNotificationClicks`), without reloading it
      const focused = await open.focus()
      const url = new URL(target)
      focused.postMessage({ type: 'navigate', url: url.pathname + url.search })
      return
    }
    await self.clients.openWindow(target)
  })())
})
